var QUESTOES_ADMINISTRACAO_PUBLICA_AGP = [{"id":18603,"enunciado":"O funcionamento racional da estrutura administrativa pressupõe uma configuração interna embasada em relações que assegurem coordenação entre as diversas unidades que desenvolvem a atividade administrativa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":18614,"enunciado":"Considere-se que uma repartição pública atua na elaboração de pareceres, editais e estudos e é composta por seção de pareceres, seção de editais e seção de estudos. Nesse caso, é correto afirmar que o critério de departamentalização adotado é o matricial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":20040,"enunciado":"Com base nos conceitos gerais e no histórico da administração, julgue o item abaixo.\n\nOs modelos de administração, organização e sociedade que emergiram da Revolução Industrial tiveram Marx como um de seus principais críticos, o qual exerceu forte influência sobre sindicatos e partidos políticos. Entre outros aspectos, Marx propunha, em contraposição ao poder dos capitalistas sobre o Estado, um modelo alternativo de gestão embasado na propriedade coletiva dos meios de produção.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":28475,"enunciado":"Se um prestador de serviços bancários estiver atendendo pessoa com menos de sessenta anos de idade, deve paralisar o atendimento para atender qualquer pessoa idosa que solicite seus serviços. Tal precedência deve-se ao fato de que as instituições bancárias devem dispensar atendimento preferencial, imediato e individualizado às pessoas idosas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":28481,"enunciado":"Segundo atuais estudos de marketing, quando um cliente procura os serviços de um banco, além da busca de uma conta-corrente, de uma linha de crédito ou de um cartão de crédito, outros valores, como status, conforto e proteção também estão sendo valorados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":28617,"enunciado":"Nas filas dos bancos, terão atendimento prioritário somente as pessoas portadoras de deficiência, os idosos com idade superior a 60 anos e as mulheres gestantes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":28623,"enunciado":"No segmento bancário, no conceito de vendas, é correto que sejam enfocados os produtos/serviços bancários, enquanto, no conceito de marketing, é correto que o foco sejam as necessidades do consumidor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":28625,"enunciado":"Atualmente, como estratégia de marketing, os bancos utilizam o marketing direto, que pode ser corretamente definido como um sistema interativo que usa uma ou mais mídias de propaganda para obter resposta e ou transação mensurável em qualquer localização.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":28628,"enunciado":"Durante uma ligação telefônica a serviço, o funcionário de um banco, visando estabelecer contato cordial e gerar empatia com o cliente do outro lado da linha, deve empregar termos como querido ou amigo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":277663,"enunciado":"A empatia é um sentimento de afinidade e de cortesia que, nas relações humanas, é essencial para garantir um bom atendimento ao público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":277665,"enunciado":"A presteza não consiste em princípio do atendimento ao público, em virtude de o respeito aos limites burocráticos do trâmite legal dos serviços ser um princípio absoluto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":277667,"enunciado":"Entre os requisitos necessários ao atendimento no serviço público inclui-se a boa apresentação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":277668,"enunciado":"O servidor público que, no exercício de suas atividades, tratar mal algum contribuinte poderá ser responsabilizado individualmente por dano moral.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":326985,"enunciado":"Acerca da qualidade no atendimento ao público nos aspectos de comunicabilidade, eficiência e presteza, julgue os próximos itens.\n\n\nDesde que o serviço prestado satisfaça às necessidades do cidadão, o tempo que ele esperar para ser atendido tornar-se-á irrelevante.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":326986,"enunciado":"Acerca da qualidade no atendimento ao público nos aspectos de comunicabilidade, eficiência e presteza, julgue os próximos itens.\n\n\nUma comunicação eficaz ocorre quando o significado pretendido da fonte e o significado percebido pelo receptor são os mesmos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":326987,"enunciado":"Acerca da qualidade no atendimento ao público nos aspectos de comunicabilidade, eficiência e presteza, julgue os próximos itens.\n\n\nO desenvolvimento do processo de qualidade e sucesso do atendimento tem início no treinamento, quando se estabelece um padrão de atendimento, e na disseminação de informações para que o servidor adquira as condições de atender com precisão as demandas dos usuários.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":326988,"enunciado":"No que se refere à conduta e objetividade na qualidade do atendimento ao público, julgue os itens subsequentes.\n\n\nPostura ética, imparcialidade, colaboração e respeito devem ser disseminadas e incentivadas entre os servidores que prestam atendimento ao público como condição para o atingimento da excelência.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":326989,"enunciado":"No que se refere à conduta e objetividade na qualidade do atendimento ao público, julgue os itens subsequentes.\n\n\nNo serviço público, o tempo é muito importante e deve ser aproveitado ao máximo. Nesse sentido, enquanto o atendente escuta as demandas do usuário, é recomendável que ele realize outras atividades inerentes ao cargo, sempre com a preocupação de melhor aproveitar o tempo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":326990,"enunciado":"Paulina, técnica administrativa de um órgão público, possui produtividade acima da média, porém, por não estabelecer bom relacionamento com seus pares, opta por realizar seu trabalho individualmente. Acerca dessa situação hipotética e de aspectos relacionados à eficácia no comportamento interpessoal para o atendimento ao público, julgue os itens seguintes.\n\n\nA lacuna de competências interpessoais descrita na situação em apreço poderá ocasionar a redução do suporte social advindo dos colegas e que é importantíssimo para que o trabalhador consiga manter sua produtividade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":326991,"enunciado":"Paulina, técnica administrativa de um órgão público, possui produtividade acima da média, porém, por não estabelecer bom relacionamento com seus pares, opta por realizar seu trabalho individualmente. Acerca dessa situação hipotética e de aspectos relacionados à eficácia no comportamento interpessoal para o atendimento ao público, julgue os itens seguintes.\n\n\nA produtividade de um grupo e sua eficiência na prestação de serviços e no consequente alcance da qualidade no atendimento decorre da competência individual de seus membros, independentemente da solidariedade entre eles ou de suas relações interpessoais","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":343013,"enunciado":"Com relação à qualidade no atendimento, julgue os itens que se seguem.\n\nPessoas que sabem transmitir e receber mensagens, colocando-se no lugar do outro, tendem a ser bons profissionais de atendimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":343014,"enunciado":"Com relação à qualidade no atendimento, julgue os itens que se seguem.\n\nO empenho dos atendentes em resolver problemas dos clientes que vão além da atividade prescrita pode caracterizar um comportamento extrapapel.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":343015,"enunciado":"Com relação à qualidade no atendimento, julgue os itens que se seguem.\n\nUma organização que tem diretores comprometidos com a imagem da empresa seguramente presta um bom atendimento aos clientes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":343020,"enunciado":"Julgue os itens subsequentes, acerca das centrais de atendimento.\n\nAs centrais de atendimento (call centers) devem ser sempre a principal porta de entrada para os clientes de uma empresa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":343021,"enunciado":"Julgue os itens subsequentes, acerca das centrais de atendimento.\n\nA organização que tem uma ou mais linhas telefônicas usadas para atender a seus clientes pode afirmar que possui uma central de atendimento ou call center","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":343022,"enunciado":"Tendo o texto acima com referência inicial, julgue os próximos itens, relativos ao atendimento.\n\nA ineficiência simpática pode compensar eventuais pequenas falhas na prestação de serviços.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":343023,"enunciado":"Tendo o texto acima com referência inicial, julgue os próximos itens, relativos ao atendimento.\n\nPrestar um bom atendimento independe do conhecimento a respeito do perfil do público a que se pretende atender.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":343024,"enunciado":"Tendo o texto acima com referência inicial, julgue os próximos itens, relativos ao atendimento.\n\nA qualidade percebida pelos clientes a respeito dos serviços prestados por uma organização está diretamente relacionada ao atendimento recebido.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":359824,"enunciado":"Com referência ao modelo de excelência gerencial e à gestão de projetos, de processos e de qualidade, julgue os itens seguintes.\n\nNo modelo da Fundação Nacional da Qualidade, os projetos em andamento ou previstos devem ser descritos no critério denominado projetos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":420925,"enunciado":"Acerca das funções e do papel do Estado e de conceitos relacionados aos bens públicos e semipúblicos, julgue o item que se segue.\n\nA provisão de um sistema legal que permita a existência de ambiente institucional em que empresas e indivíduos possam realizar trocas voluntárias não integra as funções típicas do Estado em uma economia moderna. Após as crises de 1929 e de 2008, chegou-se à conclusão de que o sistema legal deve evitar a exploração da classe trabalhadora, limitando ao máximo a liberdade econômica.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":455892,"enunciado":"Com relação aos princípios da administração pública gerencial, julgue o  item  abaixo: \n\nA questão da flexibilidade da gestão consiste no afrouxamento do controle interno.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":455893,"enunciado":"Com relação aos princípios da administração pública gerencial, julgue o  item  abaixo: \n\nO foco no cliente implica a reversão da gratuidade de alguns serviços públicos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":455894,"enunciado":"Com relação aos princípios da administração pública gerencial, julgue o  item  abaixo: \n\nA ênfase em resultados demanda objetivos, metas e planos operacionais bem definidos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":455895,"enunciado":"Com relação aos princípios da administração pública gerencial, julgue o  item  abaixo: \n\nO controle social fundamenta-se na participação de membros da sociedade civil em instâncias executivas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":455896,"enunciado":"Com relação aos princípios da administração pública gerencial, julgue o  item  abaixo: \n\nA questão da efetividade está diretamente relacionada à satisfação do beneficiário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":455902,"enunciado":"De acordo com os princípios ideais do planejamento governamental contemporâneo, ele \n\né especializado por fases: uns planejam, outros implementam; quem planeja não implementa, quem implementa não planeja.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":455903,"enunciado":"De acordo com os princípios ideais do planejamento governamental contemporâneo, ele \nbaseia-se nos interesses e nas expectativas dos atores beneficiários ou envolvidos (stakeholders).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":455904,"enunciado":"De acordo com os princípios ideais do planejamento governamental contemporâneo, ele \n\nbaseia-se predominantemente na formulação de planos detalhados, com metas e responsabilidades bem definidas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":455905,"enunciado":"De acordo com os princípios ideais do planejamento governamental contemporâneo, ele \né periódico e seqüenciado, com prazos preestabelecidos para formulação e avaliação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":455906,"enunciado":"De acordo com os princípios ideais do planejamento governamental contemporâneo, ele \n\né referenciado em macroestratégias de desenvolvimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":483964,"enunciado":"Julgue o item seguinte referente à evolução dos modelos de administração pública.\n\nOs direitos trabalhistas, o sistema de ensino público e o sufrágio universal são iniciativas que foram instituídas no Brasil na primeira metade do século XX e que buscavam o chamado estado de bem-estar social.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":483965,"enunciado":"Julgue o item seguinte referente à evolução dos modelos de administração pública.\n\nA reforma administrativa ocorrida em 1967 pretendia o rompimento com a rigidez burocrática, e, para isso, as atividades da administração foram centralizadas e algumas instituições de administração indireta foram extintas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":483966,"enunciado":"Julgue o item seguinte referente à evolução dos modelos de administração pública.\n\nO modelo burocrático foi adotado por diversos países em substituição ao modelo patrimonialista de administração pública, no qual o patrimônio público não se distinguia do privado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":483967,"enunciado":"Julgue o item seguinte referente à evolução dos modelos de administração pública.\n\nComparativamente a outros modelos, as desvantagens do modelo burocrático incluem a sua rigidez, que pode levar à ineficiência do aparelho administrativo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":483968,"enunciado":"Julgue o item seguinte referente à evolução dos modelos de administração pública.\n\nNas gestões que adotaram os modelos gerenciais de administração pública, os quais surgiram como uma fase de modernização do modelo burocrático, o Estado permaneceu responsável pela formulação e execução de serviços prestados à sociedade de forma direta","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":483969,"enunciado":"Julgue o item seguinte referente à evolução dos modelos de administração pública.\n\nO Departamento Administrativo do Serviço Público (DASP), criado nos anos 30, tinha por objetivo a desburocratização da administração pública do Brasil mediante a modernização de estruturas e processos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":483975,"enunciado":"Julgue o item a seguir, referentes a aspectos diversos da administração pública moderna.\n\nNa administração pública, os processos podem ser caracterizados por sua abrangência. Nesse aspecto, são denominados horizontais os processos realizados inteiramente em uma unidade funcional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":483976,"enunciado":"Julgue o item a seguir, referentes a aspectos diversos da administração pública moderna.\n\nO governo empreendedor visa atender ao cidadão como cliente e, nesse atendimento, em vez de servi-lo, dá-lhe responsabilidades.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":483977,"enunciado":"Julgue o item a seguir, referentes a aspectos diversos da administração pública moderna.\n\nCom o objetivo de alcançar a excelência em seus serviços, a gestão pública empreendedora deve ter como base a avaliação contínua de suas estratégias, seus planos e suas metas pela sociedade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":483978,"enunciado":"Julgue o item a seguir, referentes a aspectos diversos da administração pública moderna.\n\nEntre outros aspectos, a gestão pública diverge da gestão privada porque, em sua totalidade, os princípios regentes daquela não são aplicáveis a esta.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":555220,"enunciado":"Com relação ao sistema político brasileiro e às relações entre Estado, governo e administração pública, julgue o item seguinte.\nO Conselho Nacional de Defesa Civil, assim como outros conselhos do Estado, conta com representantes de vários ministérios e órgãos do governo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":555224,"enunciado":"A respeito das reformas administrativas no Brasil e da organização administrativa da União, julgue o item a seguir.\nA Constituição Federal de 1988 representou um avanço à descentralização do poder público, uma vez que acrescentou poderes à administração indireta por meio da flexibilização de suas normas operacionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":555225,"enunciado":"A respeito das reformas administrativas no Brasil e da organização administrativa da União, julgue o item a seguir.\nA administração federal foi o foco do Plano Diretor da Reforma do Aparelho do Estado, que também incluiu as administrações estaduais e municipais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":555226,"enunciado":"A respeito das reformas administrativas no Brasil e da organização administrativa da União, julgue o item a seguir.\nA reforma administrativa de 1967, realizada por meio do Decreto-lei n.º 200, ampliou a administração indireta, transferindo atividades para fundações e empresas públicas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":780604,"enunciado":"Assinale o órgão de caráter consultivo contemplado no modelo de gestão e governança da UFSB, com alto grau de representatividade da comunidade externa, para contribuir com análises e tendências de longo prazo referentes a processos macrossociais e políticos pertinentes ao desenvolvimento regional.","opcoes":["Conselho Universitário","Decanato","Conselho Estratégico Social","Conselho de Ensino, Pesquisa e Extensão"],"correta":2,"explicacao":"Gabarito: <strong>Conselho Estratégico Social</strong>.","banca":"UFMT","ano":2017,"temas_relacionados":["administracao_publica_agp"]},{"id":825897,"enunciado":"Acerca de qualidade no atendimento ao público, julgue o próximo item.\n\nO servidor público cumpre o princípio da eficiência quando atende o usuário de forma objetiva, com atenção e buscando alternativas para sanar suas dúvidas ou resolver seus problemas dentro dos limites da lei.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":825898,"enunciado":"Acerca de qualidade no atendimento ao público, julgue o próximo item.\n\nA Carta de serviços ao cidadão é um instrumento instituído pelo Decreto n.º 6.932/2009 que dispõe sobre a simplificação do atendimento público prestado ao cidadão e ratifica a dispensa do reconhecimento de firma em documentos produzidos no Brasil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":825899,"enunciado":"Acerca de qualidade no atendimento ao público, julgue o próximo item.\n\nEntre outras finalidades, a Carta de serviços ao cidadão prevê o estímulo ao controle social mediante a adoção de mecanismos que possibilitem a manifestação, porém sem a participação efetiva dos usuários, na definição e avaliação de padrões de atendimento dos serviços públicos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":825900,"enunciado":"Acerca de qualidade no atendimento ao público, julgue o próximo item.\n\nO processo de atendimento no serviço público gera problemas no que se refere à cortesia dos agentes públicos. Nesse sentido, uma das diretrizes da Carta de serviços ao cidadão é respeitar o direito do cidadão de obter todas as informações necessárias às etapas do atendimento e buscar a informação apenas nos canais previamente informados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":825901,"enunciado":"Acerca de qualidade no atendimento ao público, julgue o próximo item.\n\nA comunicação entre entidade e cidadão poderá ser feita por qualquer meio, inclusive comunicação verbal, direta ou telefônica, correspondência, telegrama, fax ou correio eletrônico, registrando-se a circunstância no processo caso necessário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":933872,"enunciado":"Com relação às funções da Administração, julgue o item a seguir.\n\n\n\n\nO planejamento, na Reforma Administrativa de 1967, como um dos princípios fundamentais da Administração Federal, tem, entre os seus instrumentos básicos, a programação financeira de desembolso.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":933873,"enunciado":"Com relação às funções da Administração, julgue o item a seguir.\n\n\n\n\nO CFBio, na condição de associação, é competente para subsidiar a função de controle exercida pelo Tribunal de Contas da União (TCU), denunciando irregularidades ou ilegalidades.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":933874,"enunciado":"Com relação às funções da Administração, julgue o item a seguir.\n\n\n\n\nA abrangência das ações de fiscalização do sistema de controle interno de cada Poder compreende a concessão de benefícios, pelo Poder Público, que correspondam a tratamento diferenciado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":933875,"enunciado":"Com relação às funções da Administração, julgue o item a seguir.\n\n\n\n\nA função de organização consiste essencialmente em combinar recursos para a realização das atividades que viabilizem a consecução dos objetivos determinados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":933879,"enunciado":"Acerca de estrutura organizacional, julgue o próximo item.\n\n\n\n\nA estrutura organizacional informal forma-se por meio das relações interpessoais. Não é oficial e reflete as ligações espontâneas entre os integrantes da organização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":933881,"enunciado":"Acerca de estrutura organizacional, julgue o próximo item.\n\n\nO tipo orgânico é um modelo adaptado a condições estáveis, previsíveis, em que a definição de tarefas tende a manter-se inalterada por longos períodos de tempo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":967310,"enunciado":"No que se refere à Administração Pública, julgue o item.\n\n\n\n\nO controle deve ser exercido pelas instâncias superiores em relação às instâncias inferiores e por estas em relação àquelas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":967311,"enunciado":"A respeito dos tipos de gestão na Administração Pública, julgue o item.\n\n\n\n\nOs objetivos dos processos de negócio devem ser diferentes dos objetivos dos colaboradores da organização.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":967312,"enunciado":"A respeito dos tipos de gestão na Administração Pública, julgue o item.\n\n\n\n\nA multifuncionalidade necessária à implementação de uma gestão de processos eficaz ocorre com maior facilidade nas pequenas e microempresas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":967313,"enunciado":"A respeito dos tipos de gestão na Administração Pública, julgue o item.\n\n\n\n\nDe acordo com o modelo de gestão da qualidade, a estrutura das organizações deve ser linear, contínua e sequencial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":972226,"enunciado":"A respeito da organização interna das organizações e de seu relacionamento com o público externo, julgue o item\n\nA adhocracia é um sistema organizacional que se baseia na criação de grupos de tamanho variável para a execução de um projeto específico, findo o qual o grupo será dissolvido.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":972228,"enunciado":"A respeito da organização interna das organizações e de seu relacionamento com o público externo, julgue o item\n\n\n\n\nA qualidade do produto é um fator mais determinante para a manutenção da fidelidade dos clientes que a qualidade do atendimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":972229,"enunciado":"A respeito da organização interna das organizações e de seu relacionamento com o público externo, julgue o item\n\n\nO nível de satisfação dos clientes, tanto em termos positivos quanto em termos negativos, provoca o surgimento de um efeito multiplicador no mercado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":977731,"enunciado":"No que diz respeito à qualidade no atendimento ao público e a trabalho em equipe, julgue o item.\n\n\n\n\nNas organizações contemporâneas, a qualidade no atendimento ao cliente é considerada como um diferencial competitivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":977732,"enunciado":"No que diz respeito à qualidade no atendimento ao público e a trabalho em equipe, julgue o item.\n\n\n\n\nNo atendimento telefônico, é sempre importante primeiro identificar-se e, em seguida, perguntar quem está falando.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":977733,"enunciado":"No que diz respeito à qualidade no atendimento ao público e a trabalho em equipe, julgue o item.\n\n\n\n\nSão fatores que influenciam no atendimento telefônico a vestimenta do atendente, sua higiene e sua aparência.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":977734,"enunciado":"No que diz respeito à qualidade no atendimento ao público e a trabalho em equipe, julgue o item.\n\n\n\n\nÉ fundamental o trabalho em equipe, pois o êxito da organização depende da habilidade que os indivíduos têm de se comunicar entre si.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":977735,"enunciado":"No que diz respeito à qualidade no atendimento ao público e a trabalho em equipe, julgue o item.\n\n\n\n\nNa qualidade no atendimento ao cliente, não é considerado o fator cortesia do atendente, uma vez que o foco é a qualidade da informação, e não o tratamento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":977736,"enunciado":"No que diz respeito à qualidade no atendimento ao público e a trabalho em equipe, julgue o item.\n\n\n\n\nPara ampliar a qualidade no atendimento, alguns fatores devem ser observados e aprimorados, a exemplo da agilidade e da personalização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":977737,"enunciado":"No que diz respeito à qualidade no atendimento ao público e a trabalho em equipe, julgue o item.\n\n\n\n\nUma única pessoa que use práticas de melhoria da qualidade pode fazer uma grande diferença em uma organização e, portanto, o trabalho em equipe é secundário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":977738,"enunciado":"No que diz respeito à qualidade no atendimento ao público e a trabalho em equipe, julgue o item.\n\n\n\n\nPara alcançar as mudanças quanto ao estilo da administração, é essencial o trabalho em equipe e bons líderes de equipe, unindo esforços consistentes e conhecimentos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":977739,"enunciado":"No que diz respeito à qualidade no atendimento ao público e a trabalho em equipe, julgue o item.\n\n\n\n\nO processo de melhoramento da equipe é um evento de aprendizagem e, se todos da empresa participassem de uma equipe ao mesmo tempo, não mais ocorreriam problemas de comunicação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":977740,"enunciado":"No que diz respeito à qualidade no atendimento ao público e a trabalho em equipe, julgue o item.\n\n\n\n\nOs fatores que mais influenciam no relacionamento interpessoal são respeito, amizade, cordialidade nas relações, cooperação e entrosamento dentro e fora da organização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":986801,"enunciado":"No que se refere às funções da administração, à estrutura organizacional e à cultura organizacional, julgue o item a seguir.\n\n\n\n\nA organização é a função administrativa que determina antecipadamente quais são os objetivos a serem atingidos e como se deve fazer para alcançá‐los.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":986802,"enunciado":"No que se refere às funções da administração, à estrutura organizacional e à cultura organizacional, julgue o item a seguir.\n\n\n\n\nNa etapa de organização, são determinadas as atividades específicas necessárias ao alcance dos objetivos planejados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":986804,"enunciado":"No que se refere às funções da administração, à estrutura organizacional e à cultura organizacional, julgue o item a seguir.\n\n\n\n\nUma das características da organização linear é a presença de uma autoridade funcional ou dividida, baseada na especialização.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":986805,"enunciado":"No que se refere às funções da administração, à estrutura organizacional e à cultura organizacional, julgue o item a seguir.\n\n\n\n\nEntre as desvantagens da organização linear, é possível citar a estabilidade e a constância das relações formais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":988846,"enunciado":"Quanto à qualidade no atendimento ao público e a trabalho em equipe, julgue o item que se segue.\n\n\n\n\nDurante o processo de atendimento, expressões negativas como “não pode!” devem ser evitadas para não causar desconforto para o cliente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":988847,"enunciado":"Quanto à qualidade no atendimento ao público e a trabalho em equipe, julgue o item que se segue.\n\n\n\n\nO atendimento ao cliente é um dos aspectos de maior importância para o negócio de uma empresa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":988848,"enunciado":"Quanto à qualidade no atendimento ao público e a trabalho em equipe, julgue o item que se segue.\n\n\n\n\nNo processo de atendimento, a empatia pode ser gerada a partir de um atendimento personalizado, que faça a pessoa se sentir importante.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":988849,"enunciado":"Quanto à qualidade no atendimento ao público e a trabalho em equipe, julgue o item que se segue.\n\n\n\n\nO atendimento não influencia diretamente na decisão de compra pelo cliente. Se o produto for bom, o atendimento se torna irrelevante quanto ao poder de decisão de compra.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":988850,"enunciado":"Quanto à qualidade no atendimento ao público e a trabalho em equipe, julgue o item que se segue.\n\n\n\n\nPode-se chamar de empresa de qualidade a empresa que satisfaça a maioria das necessidades de seus consumidores na maior parte do tempo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":988852,"enunciado":"Quanto à qualidade no atendimento ao público e a trabalho em equipe, julgue o item que se segue.\n\n\n\n\nO trabalho em equipe distingue-se do trabalho em grupo pela predominância da unidade de espírito, da coesão, das relações interpessoais, do engajamento pessoal e da adesão total dos membros ao grupo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":989096,"enunciado":"A respeito dos conceitos de Estado e de Administração Pública, julgue o item a seguir.\n\n\n\n\nNo regime federativo brasileiro, a ideia de Estado em sentido amplo se identifica com a de União, ente dotado constitucionalmente de mais poderes e de maior autonomia.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":989097,"enunciado":"A respeito dos conceitos de Estado e de Administração Pública, julgue o item a seguir.\n\n\n\n\nO Estado de direito é ente que, ao mesmo tempo em que produz lei, a ela se submete.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":989098,"enunciado":"A respeito dos conceitos de Estado e de Administração Pública, julgue o item a seguir.\n\n\n\n\nA função administrativa desempenhada por entidades e órgãos estatais é essencialmente mais caracterizada por seu conteúdo, a atividade em si, que pelo Poder ou ente de que provenha. Trata‐se, pois, da dimensão objetiva do conceito de administração pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":989099,"enunciado":"A respeito dos conceitos de Estado e de Administração Pública, julgue o item a seguir.\n\n\n\n\nSob a ótica subjetiva, a Administração Pública se confunde com o Poder Executivo, embora acidental e excepcionalmente possa congregar órgãos dos demais Poderes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":989104,"enunciado":"Acerca dos agentes públicos, julgue o item a seguir.\n\n\n\n\nOs agentes políticos caracterizam‐se, mais que por um mandato, pela transitoriedade de suas funções, como é o caso dos ministros de Estado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":989105,"enunciado":"Acerca dos agentes públicos, julgue o item a seguir.\n\n\n\n\nOs agentes particulares colaboradores exercem funções em razão de um vínculo que os liga ao Estado e se orientam pelo interesse coletivo, não percebendo qualquer sorte de remuneração ou de benefício indireto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":989128,"enunciado":"Julgue o item a seguir.\n\n\n\n\nOs sistemas de gestão da qualidade podem ser auditados e certificados. A Norma ISO 9001 é o padrão mais conhecido para certificações. A adoção da Norma pela empresa é a garantia da qualidade de seus produtos/serviços, auditada diretamente pela ISO.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":989256,"enunciado":"Julgue o item.\nConsiderar o atendimento ao cliente como um trabalho de rotina equivale a tratar cada cliente como apenas mais um. O tratamento tem de ser diferenciado, assim como têm de ser diferenciadas as necessidades de cada pessoa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":989257,"enunciado":"Julgue o item.\nUma das recomendações de um call center para atendimento telefônico é a utilização de termos técnicos que evidenciem a competência da empresa e o conhecimento do atendente sobre a questão que constitui o objeto da reclamação do cliente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1011336,"enunciado":"Julgue o item, relativo à qualidade em prestação de serviços.\n\n\n\n\nA qualidade técnica de um serviço pode ser analisada como o resultado de um atendimento ao cliente, o que foi entregue ao cliente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1011337,"enunciado":"Julgue o item, relativo à qualidade em prestação de serviços.\n\n\n\n\nA solução conforme a demanda do cliente e a entrega no prazo são exemplos de qualidade funcional do serviço.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1011338,"enunciado":"Julgue o item, relativo à qualidade em prestação de serviços.\n\n\n\n\nProfissionalismo, boa vontade e respeito ao público são requisitos de um atendimento de boa qualidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1011339,"enunciado":"Julgue o item, relativo à qualidade em prestação de serviços.\n\n\n\n\nConfiabilidade, cortesia, empatia, segurança, aparência do atendente e do ambiente e prontidão para resolver o problema são exemplos de qualidade funcional de um serviço.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1011340,"enunciado":"Julgue o item, relativo à qualidade em prestação de serviços.\n\n\n\n\nPode‐se definir a qualidade funcional com base somente no usuário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1011352,"enunciado":"Julgue o item.\n\n\n\n\nNa comunicação telefônica, o funcionário deve informar os procedimentos em andamento para que o cliente perceba o que está sendo feito e não fique pensando que o atendente não está mais na linha ou não está atendendo sua demanda. O nome dessa técnica é oferecer controle percebido.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1013066,"enunciado":"Julgue o item a seguir, relativo a atendimento ao público.\n\n\n\n\nO atendimento prioritário, regulamentado por lei, compreende tratamento imediato, mas não tratamento diferenciado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1013067,"enunciado":"Julgue o item a seguir, relativo a atendimento ao público.\n\n\n\n\nA prestação da informação correta, a brevidade na resposta, a adequação do ambiente para a realização do atendimento e a cortesia do servidor fundamentam a qualidade do atendimento ao público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1013068,"enunciado":"Julgue o item a seguir, relativo a atendimento ao público.\n\n\n\n\nEm casos complexos, o atendimento ao público deverá ser realizado de forma impessoal, preferivelmente por meios eletrônicos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1013069,"enunciado":"Julgue o item a seguir, relativo a atendimento ao público.\n\n\n\n\nO grau de satisfação do usuário do serviço consiste em fator subjetivo de avaliação, não podendo ser considerado como indicador de qualidade do atendimento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1013070,"enunciado":"Julgue o item a seguir, relativo a atendimento ao público.\n\n\n\n\nNo atendimento ao público, a capacidade de ouvir do servidor fortalece a comunicabilidade e a tolerância nas interações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1030953,"enunciado":"Julgue o item.\n\n\n\n\nNa Administração Pública Federal, para efeito do controle de suas atividades, é irrelevante o fato de o seu custo ser superior ao risco.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1030954,"enunciado":"Julgue o item.\n\n\n\n\nA chamada Lei de Acesso à Informação é um poderoso instrumento de controle social. O acesso de qualquer cidadão está condicionado à explicitação dos motivos determinantes das informações.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1030967,"enunciado":"Julgue o item.\n\nUma dica para um bom atendimento ao cliente ou usuário, quando o funcionário estiver realizando um outro serviço determinado pelo seu chefe, é explicar que fará o atendimento logo que possível.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1030968,"enunciado":"Julgue o item.\n\n\n\n\nNo atendimento telefônico, recomenda‐se que o funcionário transmita o máximo de informações ou esclareça o máximo de dúvidas no menor tempo possível, para evitar divagações por parte do cliente/usuário e, assim, aumentar o tempo de espera de outros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1033910,"enunciado":"Julgue o item.\n\n\n\n\nO orçamento monetário é um dos instrumentos básicos da ação governamental.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1033911,"enunciado":"Julgue o item.\n\n\n\n\nA chamada Lei de Acesso à Informação é um poderoso instrumento de controle social. A classificação do sigilo de informações no grau de reservado é de competência das autoridades que exerçam funções de direção, comando ou chefia em qualquer nível da Administração.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1033924,"enunciado":"Julgue o item.\n\n\n\n\nEntre as dicas para um bom atendimento ao cliente ou usuário, sem prejuízo da verdade, nunca se deve admitir abertamente que a organização tenha cometido uma falha, sob pena de perder a credibilidade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1033925,"enunciado":"Julgue o item.\n\n\n\n\nNo atendimento telefônico, recomenda‐se que o funcionário utilize uma linguagem informal, gerando, assim, um clima de descontração e confiança com o cliente/usuário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039060,"enunciado":"Considerando que a conduta do servidor público deva ser baseada em padrões éticos, julgue o item subsequente.\n\n\n\n\nA impessoalidade é um princípio da Administração Pública que pressupõe tratamento equânime a todos os cidadãos, efetivando a máxima de que todos são iguais perante a lei.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039130,"enunciado":"Com relação à qualidade no atendimento ao público, julgue o item a seguir.\n\n\n\n\nNo atendimento por telefone, deve-se procurar ser o mais informal possível para deixar o público mais à vontade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039131,"enunciado":"Com relação à qualidade no atendimento ao público, julgue o item a seguir.\n\n\n\n\nÉ necessário responder às solicitações por telefone em um curto período. Na ausência da ligação, o interlocutor não poderá esperar durante longos períodos para esclarecer uma dúvida.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039132,"enunciado":"Com relação à qualidade no atendimento ao público, julgue o item a seguir.\n\n\n\n\nA organização do espaço é um dos aspectos que demonstram a qualidade do serviço de atendimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039133,"enunciado":"Com relação à qualidade no atendimento ao público, julgue o item a seguir.\n\n\n\n\nPode-se atender o público enquanto se realiza outras tarefas, desde que o atendente resolva a demanda solicitada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039134,"enunciado":"Com relação à qualidade no atendimento ao público, julgue o item a seguir.\n\n\n\n\nDeve-se evitar o jogo de responsabilidade, segundo o qual se manda o usuário de um local para outro sem solução da demanda.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039141,"enunciado":"No que se refere à postura profissional, às relações interpessoais e à comunicação, julgue o item subsequente.\n\n\n\n\nSaber ouvir é um dos aspectos menos importantes nas relações interpessoais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039142,"enunciado":"No que se refere à postura profissional, às relações interpessoais e à comunicação, julgue o item subsequente.\n\n\n\n\nManter o corpo ereto, a cabeça erguida e os braços descruzados demonstram interesse na comunicação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039143,"enunciado":"No que se refere à postura profissional, às relações interpessoais e à comunicação, julgue o item subsequente.\n\n\n\n\nOs desentendimentos quanto a valores e crenças permitem uma comunicação mais transparente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039144,"enunciado":"No que se refere à postura profissional, às relações interpessoais e à comunicação, julgue o item subsequente.\n\n\n\n\nUma das funções da comunicação é a motivação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039420,"enunciado":"No que diz respeito à qualidade no atendimento ao público, julgue o próximo item.\n\n\n\n\nNo atendimento ao público, é recomendável que se evite distrações ou a realização de atividades pessoais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039421,"enunciado":"No que diz respeito à qualidade no atendimento ao público, julgue o próximo item.\n\n\n\n\nA comunicação com o usuário deve ser feita de forma clara e, para isso, é possível empregar gírias e jargões.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1039422,"enunciado":"No que diz respeito à qualidade no atendimento ao público, julgue o próximo item.\n\n\n\n\nNo atendimento de reclamações do público, é necessário atender o usuário com atenção, mas não é preciso se desculpar pelas falhas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1055709,"enunciado":"A respeito das características da Administração Pública, julgue o iten.\n\nA Administração Pública é executora, pois ela pode ser direta ou indireta, centralizada ou descentralizada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1055710,"enunciado":"A respeito das características da Administração Pública, julgue o iten.\n\nA atividade da Administração Pública é de execução, pois presta serviços públicos e pratica atos políticos e atos de governo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1055711,"enunciado":"A respeito das características da Administração Pública, julgue o item.\n\n\n\n\nA Administração Pública é um instrumento do Estado para a promoção do desenvolvimento do País e do bem comum da sociedade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1055713,"enunciado":"A respeito das características da Administração Pública, julgue o iten.\n\nA Administração Pública possui competência ilimitada, ou seja, possui poder para decidir e comandar todas as áreas estratégicas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1055714,"enunciado":"A respeito das características da Administração Pública, julgue o iten.\n\nA Administração Pública tem poder administrativo e também político, pois suas decisões tratam de assuntos técnicos, financeiros, jurídicos, políticos, entre outros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1055741,"enunciado":"No que se refere ao atendimento ao cliente, julgue o item.\n\nO atendente pode encerrar o atendimento inicial se o consumidor se recusar a fornecer dados pessoais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1055742,"enunciado":"No que se refere ao atendimento ao cliente, julgue o item.\n\nAo falar ao telefone com o público externo, o atendente deve tratar todos com urbanidade e presteza, fornecendo as informações requeridas, ressalvadas as protegidas por sigilo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1055743,"enunciado":"No que se refere ao atendimento ao cliente, julgue o item.\n\nQuando um atendente deixa uma pessoa à espera de solução que compete ao seu setor ou permite a formação de filas desnecessárias, atua de forma antiética e causa grave dano moral aos usuários dos serviços públicos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1068166,"enunciado":"Com relação à qualidade no atendimento ao público, julgue o item seguinte.\n\n\n\n\nA demonstração de empatia às solicitações dos usuários é prescindível durante um atendimento ao público.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1068167,"enunciado":"Com relação à qualidade no atendimento ao público, julgue o item seguinte.\n\n\n\n\nDurante o atendimento ao público, deve‐se evitar a realização de críticas à instituição.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1068168,"enunciado":"Com relação à qualidade no atendimento ao público, julgue o item seguinte.\n\n\n\n\nDurante o atendimento de reclamações do público, deve‐se evitar a tomada de posturas defensivas, de modo a impedir a abertura de um registro.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1093495,"enunciado":"Com relação à centralização, à descentralização, à concentração, à desconcentração, à organização administrativa da União e à administração direta e indireta, julgue o item.\n\nAs  autarquias  são  pessoas  jurídicas  de  direito  público criadas por lei, com patrimônio e receita próprios, para executar atividades típicas da Administração Pública que requeiram,  para  seu  melhor funcionamento,  gestão administrativa e financeira descentralizada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1177855,"enunciado":"Com relação à estruturação, às características e à descrição dos órgãos da administração federal direta e indireta, julgue o item .\n\n\n\n\nSe determinada autarquia tiver um plano estratégico de reestruturação e de desenvolvimento institucional em andamento e tiver celebrado contrato de gestão com o respectivo ministério supervisor, tal autarquia poderá ser qualificada como agência executiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1252506,"enunciado":"Com relação à qualidade no atendimento ao público e ao trabalho em equipe, julgue o item.\n\n\n\n\nNa comunicação com os usuários do serviço, o profissional do atendimento ao público deve ser capaz de compreender os diferentes usos da linguagem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1252507,"enunciado":"Com relação à qualidade no atendimento ao público e ao trabalho em equipe, julgue o item.\n\n\n\n\nDeixar o cliente à espera e levar a reclamação a quem possa resolver a questão é uma ação considerada como adequada no atendimento ao cliente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1252508,"enunciado":"Com  relação  à  qualidade  no  atendimento  ao  público  e  ao  trabalho em equipe, julgue o item. \n\n\n\n\nAs  equipes  de  trabalho  têm  como  características  o  esforço  individual  e  a  responsabilidade  por  resultados  individuais,  enquanto  os  grupos  de  trabalho  são  caracterizados  por  esforço  coletivo,  objetivos  de  trabalho  compartilhados  e  responsabilidade  compartilhada pelos resultados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1252509,"enunciado":"Com  relação  à  qualidade  no  atendimento  ao  público  e  ao  trabalho em equipe, julgue o item. \n\n\n\n\nEquipes  autogerenciadas  são  formadas  por  servidores  que  executam  atividades  relacionadas  ou  interdependentes.  Esses  membros  da  equipe  exercem  muitas  das  responsabilidades  de  um  supervisor,  pois  planejam e distribuem as tarefas envolvidas no trabalho,  controlam  os  resultados  e  chegam  até  a  escolher  os  membros da equipe.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1700646,"enunciado":"Acerca da ética na função pública, julgue o item.\n\n\n\n\nA gestão pública contemporânea deve garantir mecanismos viabilizadores de uma fiscalização cidadã, a par dos controles institucionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1700679,"enunciado":"Julgue o item.\n\n\n\n\nEm um procedimento para a excelência no atendimento telefônico, o atendente deve assumir a responsabilidade pela resposta e estabelecer os encaminhamentos para a pessoa que liga e não deve negar informações nem apressar a chamada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1700680,"enunciado":"Julgue o item.\n\n\n\n\nA apresentação do servidor é um fator importante no atendimento, mas a aparência das instalações físicas não interfere na qualidade do atendimento ao público prestado por uma organização.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1748550,"enunciado":"Quanto ao atendimento ao cliente e aos elementos característicos da qualidade na prestação desse tipo de serviço, julgue o item.\n\nAtualmente, as instituições têm modernizado o atendimento ao público externo por meio de canais de atendimento on-line, como as redes sociais e o chat, nos quais o atendente pode prescindir da formalidade na comunicação com o cliente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1748551,"enunciado":"Quanto ao atendimento ao cliente e aos elementos característicos da qualidade na prestação desse tipo de serviço, julgue o item.\n\nEntre os critérios para um bom atendimento ao cliente, a cortesia é um importante fator para a qualidade do serviço prestado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1748552,"enunciado":"Quanto ao atendimento ao cliente e aos elementos característicos da qualidade na prestação desse tipo de serviço, julgue o item.\n\nO atendimento ao cliente deve ser pautado pela formalidade, pela cortesia e pela tolerância, exceto quando o cliente expressar insatisfação de modo mais enfático e descortês, pois, nesses casos, o atendente deverá se impor, espelhando o comportamento do cliente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1748553,"enunciado":"A respeito de Estado, governo e Administração Pública, julgue o item.\n\nEm linhas gerais, o Estado pode ser compreendido como uma nação politicamente organizada, dotada de soberania, com personalidade jurídica de direito privado e composta pelos Poderes Executivo, Legislativo e Judiciário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1748554,"enunciado":"A respeito de Estado, governo e Administração Pública, julgue o item.\n\nA Administração Pública, em sentido formal, orgânico ou subjetivo, pode ser conceituada como o conjunto dos órgãos e agentes públicos, dotados de prerrogativas e sujeições e destinados à satisfação do interesse público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1748557,"enunciado":"A respeito de Estado, governo e Administração Pública, julgue o item.\n\nDe acordo com o princípio da publicidade, todos os atos da Administração Pública devem ser públicos, sendo-lhe vedada a prática de quaisquer atos de natureza sigilosa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1748558,"enunciado":"A respeito de Estado, governo e Administração Pública, julgue o item.\n\nO princípio do devido processo legal é considerado como um superprincípio, norteador de todo o ordenamento jurídico, do qual decorrem, entre outros, os princípios do contraditório e da ampla defesa, cuja garantia impõe à autoridade competente uma atuação conforme o direito, facultando-lhe atuar com arbitrariedades.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1748559,"enunciado":"A respeito de Estado, governo e Administração Pública, julgue o item.\n\nA Administração pode anular seus próprios atos quando eivados de vícios que os tornem ilegais, uma vez que deles não se originam direitos, ou revogá-los, por motivo de conveniência ou oportunidade, respeitados os direitos adquiridos e não sendo possível a apreciação judicial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1748560,"enunciado":"A respeito de Estado, governo e Administração Pública, julgue o item.\n\nAs autarquias, as empresas públicas, as sociedades de economia mista e as fundações públicas são entidades autônomas, com personalidade jurídica própria, que compõem a administração pública direta. Essas entidades vinculam-se ao Ministério em cuja área de competência estiver enquadrada sua principal atividade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1748561,"enunciado":"A respeito de Estado, governo e Administração Pública, julgue o item.\n\nA autarquia é uma entidade integrante da administração indireta, criada por lei, com personalidade jurídica, patrimônio e receita próprios, para executar atividades típicas da Administração Pública que requeiram, para seu melhor funcionamento, gestão administrativa e financeira descentralizada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1764870,"enunciado":"Acerca do atendimento ao cliente, julgue o item.\n\nDe acordo com Singh, as respostas emitidas por clientes insatisfeitos podem ser classificadas em três grupos: respostas por vocalização, incluindo a reclamação direta à empresa; respostas privadas, isto é, ações que envolvem comunicação boca a boca negativa a amigos e parentes; e respostas incluindo ações junto a agências externas e ações legais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1764871,"enunciado":"Acerca do atendimento ao cliente, julgue o item.\n\nUma das características do bom atendimento é a urbanidade, que é a rapidez no atendimento. Ela faz com que o cliente não perca tempo desnecessariamente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1782223,"enunciado":"No que concerne a atendimento a clientes e a atendimento  ao telefone, julgue o item.\n\n\n\n\nÉ recomendável o uso de gírias no ambiente de trabalho.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1782224,"enunciado":"No que concerne a atendimento a clientes e a atendimento  ao telefone, julgue o item.\n\n\n\n\nRecomenda‐se que, no atendimento telefônico, caso o volume esteja  baixo, se peça para a  pessoa  falar  um  pouco mais alto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1833458,"enunciado":"No que se refere ao atendimento ao público e ao atendimento telefônico, julgue o item. \n\n\n\n\nO atendimento ao público interno destina-se aos colaboradores que mantêm vínculo funcional direto, aos fornecedores e aos parceiros da instituição.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1833459,"enunciado":"No que se refere ao atendimento ao público e ao atendimento telefônico, julgue o item. \n\n\n\n\nDurante um atendimento telefônico em que o cliente telefonou para o setor errado, o melhor a ser feito é dar o telefone do setor correto para que ele obtenha a informação adequada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1840151,"enunciado":"Julgue o item, relativo ao atendimento aos clientes, inclusive por telefone.\n\n\n\n\nPara uma decisão de compra, os clientes procuram analisar os benefícios adicionais que estão recebendo, além da qualidade e do preço pago.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1840152,"enunciado":"Julgue o item, relativo ao atendimento aos clientes, inclusive por telefone.\n\n\n\n\nQuanto à qualidade almejada no atendimento, a duração do contato com o cliente é indiferente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1840153,"enunciado":"Julgue o item, relativo ao atendimento aos clientes, inclusive por telefone.\n\n\n\n\nÉ necessário se evitar a formulação de perguntas sem conteúdo e evasivas ao cliente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1840154,"enunciado":"Julgue o item, relativo ao atendimento aos clientes, inclusive por telefone.\n\n\n\n\nO uso de expressões que demonstrem empatia, como, por exemplo, “meu bem” e “meu amor”, é uma prática recomendada no atendimento telefônico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1844450,"enunciado":"Com base nas boas práticas referentes ao atendimento ao público, julgue o item.\n\n\n\n\nNa atividade de atendimento ao público, é de extrema importância dar a devida atenção ao cliente, principalmente em casos de reclamações, que deverão ser resolvidas, independentemente do prazo que seja necessário para a resolução.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1844451,"enunciado":"Com base nas boas práticas referentes ao atendimento ao público, julgue o item.\n\n\n\n\nNo atendimento ao público, a utilização de expressões verbais adequadas é essencial, pois demonstra cortesia durante o contato com o cliente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1844452,"enunciado":"Com base nas boas práticas referentes ao atendimento ao público, julgue o item.\n\n\n\n\nNo atendimento ao público via telefone, é correto afirmar que, ao transferir uma chamada, o atendente poderá utilizar expressões como “Com quem eu falo, por favor?” e “Um momento, por gentileza, estou transferindo a sua ligação”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1865501,"enunciado":"O atendimento ao público, seja externo ou interno, é uma atividade de extrema relevância em uma instituição e, com vistas à satisfação do cliente, é interessante que a organização permita que os colaboradores sejam naturais na forma de falar e de atender, prescindindo, assim, de regras e de padrões.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1865502,"enunciado":"Se, durante um atendimento via telefone, o cliente for posto em espera por um tempo demasiado longo, mas, mesmo assim, tiver seu problema resolvido, pode-se considerar que o atendimento foi executado com tempestividade e suficiência.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1865503,"enunciado":"A imagem dos atendentes pode influenciar na opinião do cliente em relação à instituição tanto de forma negativa quanto de forma positiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1907362,"enunciado":"Quanto à comunicação, julgue o item.\n\n\n\n\nNão é indicado que o emissor utilize linguagem excessivamente rebuscada para transmitir informações a pessoas com vocabulário mais restrito, pois haverá perda de informação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1907626,"enunciado":"Acerca das trajetórias gerais da administração, julgue o item a seguir.  \n\n\n\n\nA reforma gerencialista foi implementada pelo governo Fernando Henrique Cardoso, em 1995, espelhando-se em experiências adotadas na Inglaterra.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1907627,"enunciado":"Acerca das trajetórias gerais da administração, julgue o item a seguir.  \n\n\n\n\nÉ característica da organização burocrática a adoção de administração profissional em substituição ao modelo anterior, em que se praticava administração proprietária.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1907628,"enunciado":"Acerca das trajetórias gerais da administração, julgue o item a seguir.  \n\n\n\n\nA primeira reforma administrativa brasileira, de 1930, visava combater a estrutura burocrática vigente à época, inspirada nos ideais weberianos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1907641,"enunciado":"Sobre gestão de projetos e processos, julgue o seguinte item.\n\n\n\n\nOs processos organizacionais são circunscritos aos limites dos departamentos organizacionais aos quais pertencem.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1907644,"enunciado":"Sobre gestão de projetos e processos, julgue o seguinte item.\n\n\n\n\nNa administração pública, os processos centrais são aqueles orientados à prestação de serviços públicos aos cidadãos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1909186,"enunciado":"Acerca da gestão governamental, julgue o item subsequente.\nNo processo público de contratualização de resultados, três fases são importantes para o alcance dos objetivos: negociação, construção do instrumento e gerenciamento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1913260,"enunciado":"A respeito do atendimento ao público, julgue o item.\n\n\n\n\nA empatia implica a necessidade de se colocar no lugar do cliente/usuário, ou seja, de perceber suas causas como ele as percebe.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1913261,"enunciado":"A respeito do atendimento ao público, julgue o item.\n\n\n\n\nA autoestima é o modo como a pessoa se descreve e evolui com a idade, com as experiências da vida e com o conhecimento que tem de suas capacidades e limitações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1913262,"enunciado":"A respeito do atendimento ao público, julgue o item.\n\n\n\n\nEm relação à cortesia no atendimento, é importante ouvir calmamente o que o cliente/usuário tem a dizer e mostrar que o diálogo está sendo acompanhado com atenção, dando um feedback, mas não interrompendo seu raciocínio.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1913263,"enunciado":"A respeito do atendimento ao público, julgue o item.\n\n\n\n\nO estilo passivo faz com que a pessoa tenha medo de avançar e de decidir, porque receia a decepção, e tenda a se fundir com o grupo, por medo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1913264,"enunciado":"A respeito do atendimento ao público, julgue o item.\n\n\n\n\nO contexto é a mensagem que é enviada ao emissor e que lhe transmite como as suas comunicações e atitudes foram percebidas e sentidas pelo receptor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1915013,"enunciado":"No que se refere aos serviços públicos, julgue o item.\nConsideram-se como serviços administrativos aqueles que o Estado executa para mais bem compor sua organização, como, por exemplo, o que implanta centro de pesquisa ou edita a imprensa oficial para a divulgação dos atos administrativos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1917804,"enunciado":"A respeito da qualidade no atendimento ao público, julgue o item.\n\n\n\n\nPara se ter qualidade no atendimento, é necessário saber as normas da empresa e conhecer o fluxo de informação e de logística e os caminhos para resolver qualquer questão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1917805,"enunciado":"A respeito da qualidade no atendimento ao público, julgue o item.\n\n\n\n\nA qualidade no atendimento independe da forma como o profissional se comunica com o seu público e requer conhecimento técnico e administrativo e reconhecimento pessoal de como realizar tal ação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1917806,"enunciado":"A respeito da qualidade no atendimento ao público, julgue o item.\n\n\n\n\nA qualidade do atendimento está diretamente relacionada com o resultado apresentado para o problema do cidadão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1917807,"enunciado":"A respeito da qualidade no atendimento ao público, julgue o item.\n\n\n\n\nA tangibilidade, consistente nas aparências das instalações físicas, é uma característica que influencia na percepção de qualidade do atendimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1917808,"enunciado":"A respeito da qualidade no atendimento ao público, julgue o item.\n\n\n\n\nSão características gerais que precisam ser avaliadas ao se trabalhar com qualidade de serviços: tangibilidade; confiabilidade; proatividade; competência; cortesia; credibilidade; segurança; acesso; comunicação; e entendimento do cliente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1917809,"enunciado":"A respeito da qualidade no atendimento ao público, julgue o item.\n\n\n\n\nÉ muito importante resolver o problema do cliente, mas é imprescindível ouvi-lo, a fim de lhe passar segurança.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1917810,"enunciado":"A respeito da qualidade no atendimento ao público, julgue o item.\n\n\n\n\nO tempo de fila ou o tempo de espera influencia na percepção de qualidade de atendimento do cidadão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1917811,"enunciado":"A respeito da qualidade no atendimento ao público, julgue o item.\n\n\n\n\nNa qualidade do atendimento, deve-se estabelecer somente um limite: entre o que é certo e o que é errado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1917812,"enunciado":"A respeito da qualidade no atendimento ao público, julgue o item.\n\n\n\n\nÓrgãos que buscam a qualidade do atendimento direcionam o olhar externo para a cortesia, os benefícios e os canais de comunicação interativos e ágeis.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1917813,"enunciado":"A respeito da qualidade no atendimento ao público, julgue o item.\n\n\n\n\nNa definição de suas tarefas, o profissional de atendimento deve pensar de forma holística.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1926368,"enunciado":"Quanto ao atendimento ao público, julgue o item.\n\n\n\n\nA comunicação não verbal pode ser verificada por meio dos gestos, das posturas, das expressões faciais, do tom de voz, entre outros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1926369,"enunciado":"Quanto ao atendimento ao público, julgue o item.\n\n\n\n\nUm dos problemas no atendimento ao usuário ocorre quando o atendente se dirige ao usuário com um tom de superioridade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1973850,"enunciado":"A respeito da gestão de processos, julgue o item que se segue.\n\n\n\n\nEm organizações da administração pública, o atendimento ao cidadão é considerado um processo central.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1973851,"enunciado":"A respeito da gestão de processos, julgue o item que se segue.\n\n\n\n\nA gestão de contratos em uma organização pública é um exemplo de processo central.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1973852,"enunciado":"A respeito da gestão de processos, julgue o item que se segue.\n\n\n\n\nEm um órgão público, a gestão de pessoas é considerada um processo de apoio.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1973853,"enunciado":"A respeito da gestão de processos, julgue o item que se segue.\n\n\n\n\nNa gestão de processos, a fase de aprimoramento ocorre antes da fase de avaliação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1973854,"enunciado":"A respeito da gestão de processos, julgue o item que se segue.\n\n\n\n\nAs atividades de um processo são sequenciais e inter-relacionadas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1973855,"enunciado":"A respeito da gestão de processos, julgue o item que se segue.\n\n\n\n\nPara avaliar a evolução de um processo, é possível utilizar indicadores de desempenho, como os indicadores de satisfação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1996173,"enunciado":"No Brasil, a Administração Pública Gerencial foi superada pela Administração Pública 4.0, a qual foca substancialmente na democratização dos serviços ao público em geral.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IDECAN","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1996192,"enunciado":"Atendimento ao público é uma das atividades de maior relevância em uma empresa no que diz respeito com o trato ao cliente, por isso é tão importante para as organizações, estando presente em diversas discussões. Trata-se da forma como todos os funcionários interagem com o cliente, ou seja, o público, e fazem parte desse processo todas as pessoas que mantêm algum tipo de relacionamento com a empresa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IDECAN","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":1996193,"enunciado":"A opinião da gestão pública se refere à expressão, gerada por meio de um debate, de um grupo significativo da sociedade com relação a um tema de interesse coletivo. Nesse sentido, pode funcionar como um mecanismo de pressão para que governantes tomem decisões sobre algo relevante para a coletividade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IDECAN","ano":2022,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2351122,"enunciado":"Quanto à administração pública, do modelo racional legal ao paradigma pós-burocrático, julgue o item a seguir.\n\n\n\n\nO modelo de administração burocrática no Brasil surgiu ao final do processo da industrialização brasileira e modificou os critérios de aplicação do controle dos serviços públicos e as relações estabelecidas entre o poder público e seus servidores.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2351123,"enunciado":"Quanto à administração pública, do modelo racional legal ao paradigma pós-burocrático, julgue o item a seguir.\n\n\n\n\nO gerencialismo tem como pressupostos o fortalecimento do gerenciamento público e de instituições de controle e a imputação de resultados e estruturas flexíveis de tal forma que o cidadão se perceba e participe como usuário de serviços públicos e contribuinte.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2351124,"enunciado":"Julgue o item a seguir, tendo em vista convergências e diferenças entre a gestão privada e a gestão pública. \n\n\n\n\nComo prática exclusiva da gestão privada, a responsabilidade social e ambiental é uma estratégia composta por ações voluntárias de empresas em benefício da sociedade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2351125,"enunciado":"No que se refere à administração pública, seu orçamento e suas boas práticas, julgue o item a seguir.\n\n\n\n\nA excelência em gestão pública pressupõe atenção prioritária ao usuário dos serviços públicos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2351181,"enunciado":"Julgue o próximo item sobre gestão de projetos, planejamento estratégico, excelência nos serviços públicos e empreendedorismo governamental. \n\n\n\n\nPara alcançar excelência na prestação de serviços públicos, o Estado deve promover amplos debates com a sociedade para estabelecer prioridades e dar transparência quanto a seu papel e seus espaços de atuação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2351182,"enunciado":"A respeito de aspectos relativos a gestão de resultados nos serviços públicos, convergências e diferenças entre a gestão pública e a gestão privada, paradigma do cliente na gestão pública e sustentabilidade pública e acessibilidade, julgue o item  seguinte.\n\n\n\n\nOs indicadores para mensuração de resultados devem ser de fácil compreensão pelos usuários e devem possibilitar a discussão sobre os resultados obtidos e os seus impactos na organização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2351183,"enunciado":"A respeito de aspectos relativos a gestão de resultados nos serviços públicos, convergências e diferenças entre a gestão pública e a gestão privada, paradigma do cliente na gestão pública e sustentabilidade pública e acessibilidade, julgue o item  seguinte.\n\n\n\n\nA administração gerencial é um estilo de gestão que ocorre tanto na administração pública quanto na privada, sendo equiparados, em ambas as esferas, a forma de obtenção de lucros, os resultados e os interesses envolvidos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2351184,"enunciado":"A respeito de aspectos relativos a gestão de resultados nos serviços públicos, convergências e diferenças entre a gestão pública e a gestão privada, paradigma do cliente na gestão pública e sustentabilidade pública e acessibilidade, julgue o item  seguinte.\n\n\n\n\nA sustentabilidade na gestão pública está relacionada à justiça social e à viabilidade econômica no que se refere à correta exploração dos recursos naturais, desconsiderando aspectos relativos à eliminação do déficit público e à estabilização econômica.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2351185,"enunciado":"A respeito de aspectos relativos a gestão de resultados nos serviços públicos, convergências e diferenças entre a gestão pública e a gestão privada, paradigma do cliente na gestão pública e sustentabilidade pública e acessibilidade, julgue o item  seguinte.\n\n\n\n\nAo se compreender os cidadãos como clientes e usuários dos serviços públicos, exige-se das organizações públicas agilidade, busca por excelência e inovação na prestação de serviços.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2358139,"enunciado":"Julgue o item seguinte, quanto à comunicação e à excelência nos serviços públicos. \n\n\n\n\nFocar em melhoria contínua, implementar modelos de gestão orientados ao desempenho e utilizar estruturas divisionais menos burocráticas são orientações adequadas ao alcance da excelência nos serviços públicos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2358140,"enunciado":"Julgue o item seguinte, quanto à comunicação e à excelência nos serviços públicos. \n\n\n\n\nA excelência no serviço público prestado depende da prática de um pensamento sistêmico, que seja capaz de manter relações eficazes e restritas às redes formais de usuários, cidadãos e parceiros, bem como centradas nos elementos internos à organização.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2358141,"enunciado":"Julgue o item seguinte, quanto à comunicação e à excelência nos serviços públicos. \n\n\n\n\nA implementação de políticas públicas de forma eficaz e eficiente, atendendo-se aos aspectos políticos, técnicos, financeiros e gerencias, é uma maneira de promover governança e obter excelência nos serviços públicos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2358142,"enunciado":"Julgue o item seguinte, quanto à comunicação e à excelência nos serviços públicos. \n\n\n\n\nEstabelecer um fluxo aberto e contínuo de informações é essencial para que as pessoas desenvolvam comunicação, criem oportunidades de aprendizado e fortaleçam um clima organizacional satisfatório.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2358375,"enunciado":"Considerando as relações humanas, julgue o item.\n\n\n\n\nEm uma organização, os indivíduos participam de grupos sociais e mantêm‑se em constante interação social.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2358376,"enunciado":"Considerando as relações humanas, julgue o item.\n\n\n\n\nAs relações humanas desenvolvem‑se a partir dos contatos entre pessoas e grupos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2358377,"enunciado":"Considerando as relações humanas, julgue o item.\n\n\n\n\nAs pessoas são influenciadas umas pelas outras e influem nos comportamentos e nas atitudes daquelas com quem mantêm contato.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2358378,"enunciado":"Considerando as relações humanas, julgue o item.\n\n\n\n\nCada pessoa procura se ajustar às outras pessoas e aos outros grupos, visando ser compreendida e aceita, pretendendo, com isso, atender a seus interesses e a suas aspirações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2358379,"enunciado":"Considerando as relações humanas, julgue o item.\n\n\n\n\nA compreensão da natureza das relações humanas permite melhores resultados dos subordinados, além de uma atmosfera em que cada pessoa é encorajada a se expressar de forma livre.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2360461,"enunciado":"Em relação ao Estado, ao governo e à Administração Pública, julgue o item.\n\n\n\n\nEnquanto a função administrativa é exercida exclusivamente pelo chefe do Poder Executivo, a função legiferante é privativa do Poder Legislativo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2360462,"enunciado":"Em relação ao Estado, ao governo e à Administração Pública, julgue o item.\n\n\n\n\nA separação dos poderes é absoluta, não podendo um intervir sobre os outros, ainda que aquele atue extrapolando os limites legalmente conferidos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2360463,"enunciado":"Em relação ao Estado, ao governo e à Administração Pública, julgue o item.\n\n\n\n\nA Administração Pública, em sentido material, refere‑se às pessoas jurídicas de direito público interno, não compreendendo a atividade administrativa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2360464,"enunciado":"Em relação ao Estado, ao governo e à Administração Pública, julgue o item.\n\n\n\n\nA competência do Senado Federal para proceder ao julgamento do presidente da República nos crimes de responsabilidade decorre do sistema de freios e contrapesos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2360465,"enunciado":"Em relação ao Estado, ao governo e à Administração Pública, julgue o item.\n\n\n\n\nO princípio da legalidade constitui uma garantia para o cidadão, porquanto esse tem o condão de limitar o arbítrio da Administração Pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2360466,"enunciado":"Em relação ao Estado, ao governo e à Administração Pública, julgue o item.\n\n\n\n\nO Congresso Nacional constitui um dos elementos indispensáveis à formação do Estado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2360467,"enunciado":"Em relação ao Estado, ao governo e à Administração Pública, julgue o item.\n\n\n\n\nNo Brasil, o sistema de governo adotado é o presidencialismo, no qual o presidente da República reúne as funções de chefe de Estado e chefe de governo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2360468,"enunciado":"Considerando a organização administrativa da União, julgue o item.\n\n\n\n\nAs autarquias são entidades integrantes da Administração Pública direta, não possuem personalidade jurídica e gozam de prerrogativas inerentes ao ministério ao qual se encontram subordinada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2360470,"enunciado":"Considerando a organização administrativa da União, julgue o item.\n\n\n\n\nO Executivo, o Legislativo e o Judiciário são Poderes independentes e harmônicos entre si, os quais correspondem aos órgãos superiores, em relação aos demais órgãos públicos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2415267,"enunciado":"Em relação ao conceito de política pública, julgue o item a seguir.\n\n\n\n\nNo âmbito do conceito de política pública, o termo política refere-se à atividade humana ligada à obtenção e à manutenção dos recursos necessários para o exercício do poder sobre o ser humano.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2415268,"enunciado":"Em relação ao conceito de política pública, julgue o item a seguir.\n\n\n\n\nPolítica pública pode ser corretamente definida como o que o governo escolhe fazer ou não fazer, com vistas a mitigar um problema público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2415269,"enunciado":"No que se refere às tipologias e às fases das políticas públicas, julgue o item subsequente.\n\n\n\n\nA fase conhecida como identificação do problema se caracteriza por um conjunto de problemas ou temas relevantes que integram a pauta política atual e que merecem ser foco da ação governamental.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2415270,"enunciado":"No que se refere às tipologias e às fases das políticas públicas, julgue o item subsequente.\n\n\n\n\nA fase de avaliação de uma política pública é relevante para o desenvolvimento e a adaptação contínua das formas e dos instrumentos de ação pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2415271,"enunciado":"No que se refere às tipologias e às fases das políticas públicas, julgue o item subsequente.\n\n\n\n\nPolíticas distributivas, tais como regras para a segurança alimentar, são aquelas que estabelecem padrões de comportamento, serviço ou produto para sujeitos públicos e privados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2415310,"enunciado":"No que diz respeito às principais abordagens da administração, às reformas administrativas e à nova gestão pública, julgue o próximo item. \n\n\n\n\nNo processo evolutivo da administração pública, a administração gerencial destaca-se por concentrar-se no alcance de resultados, rompendo com todos os princípios da administração burocrática.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2415311,"enunciado":"No que diz respeito às principais abordagens da administração, às reformas administrativas e à nova gestão pública, julgue o próximo item. \n\n\n\n\nPrestar serviços públicos de melhor qualidade, reduzir custos e tornar a administração pública mais eficiente foram objetivos estabelecidos na Reforma do Aparelho do Estado, ocorrida a partir de 1995.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2445570,"enunciado":"Acerca do atendimento ao público, julgue o item.\n\n\n\n\nÉ recomendado ao atendente que trate bem o cliente, e de modo que ele seja tratado com muita intimidade e amabilidade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2445571,"enunciado":"Acerca do atendimento ao público, julgue o item.\n\n\n\n\nRecomenda‑se que o atendimento respeite o tempo e o espaço do cliente, de modo quem se deve dar um tempo a mais para elaborar e processar o que está sendo feito, auxiliando‑o com as informações necessárias para isso.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2501350,"enunciado":"Quanto à Constituição Federal de 1988 e à Administração Pública, julgue o item subsequente.\n\n\n\n\nOs órgãos e as entidades da Administração Pública são proibidos de, individual ou conjuntamente, realizar avaliação de políticas públicas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2505144,"enunciado":"No que concerne à qualidade no atendimento ao público, julgue o item a seguir.\nNo atendimento ao público, o atendente pode ser cortês, mas o excesso de amabilidade pode ser considerado uma atitude inconveniente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2505145,"enunciado":"No que concerne à qualidade no atendimento ao público, julgue o item a seguir.\nO atendimento deve ser realizado com presteza, de modo que ele seja executado com qualidade, independentemente do tempo em que ele seja realizado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2520116,"enunciado":"Em relação à qualidade no atendimento ao público, julgue o item em sequência. \n\n\n\n\nNo atendimento ao público, o atendente pode ser cortês, e isso implica que ele pode atuar com muita intimidade em relação aos clientes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2520117,"enunciado":"Em relação à qualidade no atendimento ao público, julgue o item em sequência. \n\n\n\n\nO atendimento deve ser feito com presteza, de modo que ele seja feito de forma ágil, sem deixar de lado a qualidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2562957,"enunciado":"Quanto ao atendimento ao público, julgue o item a seguir.\n\n\n\n\nNa formação do temperamento, são incluídos tanto os elementos geneticamente herdados, como também os adquiridos do meio ambiente no qual a criança está inserida.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2562958,"enunciado":"Quanto ao atendimento ao público, julgue o item a seguir.\n\n\n\n\nA sociedade está ciente de que o serviço público deve ser eficiente, e, por isso, uma nova política de recursos humanos é necessária, para tornar os servidores mais críticos, competentes, inovadores e cientes de sua missão pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2665263,"enunciado":"A respeito do atendimento ao público, julgue o item a seguir.\n\nO início do processo de atendimento que busca a satisfação dos clientes ocorre com o mapeamento das necessidades do cliente, por meio de uma comunicação clara e objetiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":2665264,"enunciado":"A respeito do atendimento ao público, julgue o item a seguir.\n\nA presteza no atendimento é incapaz de fazer com que a organização seja vista pelo cliente como focada neste.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3028272,"enunciado":"Em uma organização pública, a escolha da estrutura organizacional é fundamental para o sucesso na execução das suas atividades. Qual tipo de estrutura organizacional é a mais apropriada para uma organização que precisa de flexibilidade e inovação, permitindo que seus funcionários trabalhem em múltiplos projetos simultaneamente?","opcoes":["Estrutura funcional.","Estrutura matricial.","Estrutura linear.","Estrutura divisional.","Estrutura em rede."],"correta":1,"explicacao":"Gabarito: <strong>Estrutura matricial.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["administracao_publica_agp"]},{"id":3028273,"enunciado":"No contexto da administração pública, o processo organizacional é composto por diversas etapas que visam garantir a eficiência e a eficácia dos serviços prestados. A etapa do processo organizacional que envolve a definição de objetivos e a escolha dos melhores meios para alcançá-los é denominada:","opcoes":["direção.","controle.","planejamento.","avaliação.","comunicação."],"correta":2,"explicacao":"Gabarito: <strong>planejamento.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["administracao_publica_agp"]},{"id":3028288,"enunciado":"Julgue as sentenças abaixo como VERDADEIRAS ou FALSAS. 1.( ) As organizações modernas buscam não apenas o lucro ou o cumprimento de metas institucionais, mas também a sustentabilidade a longo prazo. Isso inclui práticas responsáveis em termos ambientais, sociais e econômicos, assegurando a perenidade da organização. 2.( ) Em um ambiente em constante mudança, as organizações formais modernas devem ser capazes de inovar e se adaptar rapidamente às novas condições do mercado, às regulamentações e às expectativas dos clientes ou cidadãos. 3.( ) Especialmente em organizações públicas, a transparência nas operações e a prestação de contas são fundamentais para manter a confiança do público e garantir a legitimidade das ações e decisões. A sequência correta é:","opcoes":["1.V, 2.V, 3. F.","1.F, 2.V, 3.V.","1.V, 2.V, 3.V.","1.V, 2.F, 3. V.","1.V, 2.F, 3. F."],"correta":2,"explicacao":"Gabarito: <strong>1.V, 2.V, 3.V.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["administracao_publica_agp"]},{"id":3046828,"enunciado":"Julgue o item a seguir.\n\nHá certos aspectos do serviço público que não se medem pelo simples cumprimento exterior das normas (como o atendimento ao público ou os serviços de saúde), mas pela qualidade com que as regras são observadas e desta forma contribuem para o melhor desenvolvimento da função pública a qual se relaciona.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3091987,"enunciado":"Julgue o item seguinte, relativo à administração pública — do modelo racional-legal ao paradigma pós-burocrático —, ao empreendedorismo governamental e novas lideranças no setor público, à gestão por resultados na produção de serviços públicos e à governabilidade e governança. \n\n\n\n\nA gestão orientada para resultados efetivos depende, especialmente, do nível de qualificação profissional e remuneração das carreiras de Estado, bem como da geração de estímulos para a formação de novas lideranças no setor público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3091988,"enunciado":"Julgue o item seguinte, relativo à administração pública — do modelo racional-legal ao paradigma pós-burocrático —, ao empreendedorismo governamental e novas lideranças no setor público, à gestão por resultados na produção de serviços públicos e à governabilidade e governança. \n\n\n\n\nA governança refere-se, entre outros aspectos, à capacidade dos poderes públicos de intermediar os interesses da sociedade civil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3091989,"enunciado":"Julgue o item seguinte, relativo à administração pública — do modelo racional-legal ao paradigma pós-burocrático —, ao empreendedorismo governamental e novas lideranças no setor público, à gestão por resultados na produção de serviços públicos e à governabilidade e governança. \n\n\n\n\nO paradigma para a ação pública centrada no Estado regulador busca a redução da intervenção direta e a ampliação de suas capacidades de coordenação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3091990,"enunciado":"Julgue o item seguinte, relativo à administração pública — do modelo racional-legal ao paradigma pós-burocrático —, ao empreendedorismo governamental e novas lideranças no setor público, à gestão por resultados na produção de serviços públicos e à governabilidade e governança. \n\n\n\n\nA visão de governo empreendedor se baseia na prestação de serviço mais eficiente para a população, apoiado nas práticas burocráticas e na busca de uma gestão por resultados, da promoção da transparência e do controle social.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3091991,"enunciado":"Em relação às políticas públicas, julgue o item a seguir.\n\n\n\n\nCaracteriza-se como determinante estrutural da corrupção a maior dificuldade que certas estruturas burocráticas impõem aos agentes econômicos, o que aumenta a possibilidade de corrupção para se contornarem os empecilhos impostos pelo excesso de legislação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3091992,"enunciado":"Em relação às políticas públicas, julgue o item a seguir.\n\n\n\n\nNa análise custo-benefício aplicada à política pública, é possível comparar os custos monetários com os impactos positivos e benefícios gerados por um programa governamental.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3091993,"enunciado":"Em relação às políticas públicas, julgue o item a seguir.\n\n\n\n\nUma política pública começa após a formulação de alternativas para a resolução de um problema, visto que, para que um problema comece a ser resolvido, é necessário que se encontrem soluções para ele na agenda do governo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3091994,"enunciado":"Em relação às políticas públicas, julgue o item a seguir.\n\n\n\n\nNo processo de formulação de políticas públicas, os atores interagem, alocam recursos, constroem coalizões e resolvem conflitos em um cenário político.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3198486,"enunciado":"Quanto ao atendimento ao público, julgue o item seguinte.\n\n\n\n\nO bom atendimento deve prezar pelo uso de linguagem clara e compreensível, haja vista que parte dos usuários pode não compreender jargões e termos técnicos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3198487,"enunciado":"Quanto ao atendimento ao público, julgue o item seguinte.\n\n\n\n\nO princípio da competência no atendimento prevê que deve haver empenho para que o usuário não se sinta abandonado, desamparado e sem assistência.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3274503,"enunciado":"A respeito da comunicação, julgue o item seguinte.\n\n\n\n\nFalta de disposição para falar, desatenção e reação apressada às mensagens são exemplos de dificuldades que comprometem o desempenho dos emissores das mensagens.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3448655,"enunciado":"Governança pública é um conceito operacional voltado à execução de políticas públicas, enquanto gestão pública trata das diretrizes estratégicas e normativas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3448658,"enunciado":"A gestão por resultados na produção de serviços públicos prioriza a entrega de bens tangíveis, com foco no produto final e não no impacto das ações governamentais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3448661,"enunciado":"A busca pela excelência nos serviços públicos está associada à adoção de modelos de qualidade total, foco no cidadão e melhoria contínua dos processos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3448662,"enunciado":"Sustentabilidade pública é um conceito restrito à preservação ambiental nas ações do governo, com pouco vínculo com a gestão financeira ou social.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3448664,"enunciado":"Inovação na gestão pública é um conceito prioritariamente relacionado à adoção de tecnologias digitais e automação de processos burocráticos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3610563,"enunciado":"No que diz respeito à empatia e à compreensão mútua, julgue o item seguinte.\n\n\n\n\nUm empregado solicitar feedback a respeito de sua compreensão das tarefas e dos prazos junto a sua equipe é positivo ao demonstrar atenção aos seus objetivos e aos de sua equipe.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759554,"enunciado":"Acerca dos princípios fundamentais da Administração Pública, julgue o item a seguir.\n\nSão princípios expressos na Constituição Federal de 1988, aplicáveis à Administração Pública Direta e indireta, a legalidade, a impessoalidade, a moralidade, a publicidade e a eficácia.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759555,"enunciado":"Acerca dos princípios fundamentais da Administração Pública, julgue o item a seguir.\n\nOs princípios fundamentais da Administração Pública são válidos no âmbito dos Poderes da União, não se aplicando aos estados federados e nem aos municípios.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759556,"enunciado":"Acerca dos princípios fundamentais da Administração Pública, julgue o item a seguir.\n\nA ineficiência de um servidor ou de um agente público pode ensejar a perda do cargo ou da função e causar a demissão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759557,"enunciado":"Acerca dos princípios fundamentais da Administração Pública, julgue o item a seguir.\n\nO princípio da moralidade administrativa impede o reconhecimento pela Administração Pública de prescrição ou decadência para a ação disciplinar.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759571,"enunciado":"A publicidade é princípio constitucional expresso e deve balizar a atuação de todos os agentes públicos, não apenas publicando as informações nos meios oficiais, mas assegurando o efetivo acesso à informação da atuação estatal por todos os cidadãos. Acerca da legislação de referência, julgue o item a seguir.\n\nEm razão de sua imprescindibilidade à segurança da sociedade ou do Estado, as informações da Administração Pública poderão ser classificadas como ultrassecretas pelo prazo de até 25 anos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759594,"enunciado":"No setor de atendimento ao público de uma organização pública, trabalham quatro servidores:\n\n• Ana, em vez de apenas dizer “não sei”, ela se prontifica a procurar a informação em outro setor ou a ligar para um colega para obter a resposta correta;\n• Clara é conhecida pela paciência e calma ao lidar com usuários que podem estar frustrados e irritados;\n• João mantém o sigilo e a confidencialidade das informações pessoais do usuário; e\n• Paulo explica a solução do problema de forma direta e clara, sem rodeios.\n\nCom base nessa situação hipotética, julgue o item a seguir, acerca das características preponderantes da qualidade do atendimento de cada servidor.\n\nO atendimento de Ana é marcado pela conduta ética, enquanto o de Clara pelo interesse em resolver os problemas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759595,"enunciado":"No setor de atendimento ao público de uma organização pública, trabalham quatro servidores:\n\n• Ana, em vez de apenas dizer “não sei”, ela se prontifica a procurar a informação em outro setor ou a ligar para um colega para obter a resposta correta;\n• Clara é conhecida pela paciência e calma ao lidar com usuários que podem estar frustrados e irritados;\n• João mantém o sigilo e a confidencialidade das informações pessoais do usuário; e\n• Paulo explica a solução do problema de forma direta e clara, sem rodeios.\n\nCom base nessa situação hipotética, julgue o item a seguir, acerca das características preponderantes da qualidade do atendimento de cada servidor.\n\n\nJoão vale‑se da sua comunicabilidade e Paulo usa de sua tolerância.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759596,"enunciado":"No setor de atendimento ao público de uma organização pública, trabalham quatro servidores:\n\n• Ana, em vez de apenas dizer “não sei”, ela se prontifica a procurar a informação em outro setor ou a ligar para um colega para obter a resposta correta;\n• Clara é conhecida pela paciência e calma ao lidar com usuários que podem estar frustrados e irritados;\n• João mantém o sigilo e a confidencialidade das informações pessoais do usuário; e\n• Paulo explica a solução do problema de forma direta e clara, sem rodeios.\n\nCom base nessa situação hipotética, julgue o item a seguir, acerca das características preponderantes da qualidade do atendimento de cada servidor.\n\nAna emprega o interesse para solucionar os desafios, ao passo que João concentra‑se na sua habilidade de discrição.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759597,"enunciado":"No setor de atendimento ao público de uma organização pública, trabalham quatro servidores:\n\n• Ana, em vez de apenas dizer “não sei”, ela se prontifica a procurar a informação em outro setor ou a ligar para um colega para obter a resposta correta;\n• Clara é conhecida pela paciência e calma ao lidar com usuários que podem estar frustrados e irritados;\n• João mantém o sigilo e a confidencialidade das informações pessoais do usuário; e\n• Paulo explica a solução do problema de forma direta e clara, sem rodeios.\n\nCom base nessa situação hipotética, julgue o item a seguir, acerca das características preponderantes da qualidade do atendimento de cada servidor.\n\nClara utiliza a tolerância em suas tratativas com os usuários e Paulo aplica a sua objetividade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759598,"enunciado":"No que se refere ao atendimento telefônico e presencial e ao atendimento a clientes internos e externos, julgue o item a seguir.\n\nEnquanto o atendimento telefônico é assinalado pela humanização e empatia, o atendimento presencial requer o imediatismo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759599,"enunciado":"No que se refere ao atendimento telefônico e presencial e ao atendimento a clientes internos e externos, julgue o item a seguir.\n\nO foco da comunicação, tanto na interação com o cliente interno quanto externo, deve estar na comunicação clara e cordial, bem como nas soluções das necessidades.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759752,"enunciado":"Acerca da referência à organização da Administração Pública brasileira, julgue o item seguinte.\n\n\n\n\nA administração indireta apresenta potenciais dificuldades no controle finalístico pelo ente central e, em alguns casos, menos transparência e maior risco financeiro.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759753,"enunciado":"Acerca da referência à organização da Administração Pública brasileira, julgue o item seguinte.\n\n\n\n\nOs princípios da Administração Pública são revestidos de caráter mandatório, não constituindo meras recomendações e, sim, comandos obrigatórios que limitam a atuação do Poder Público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759754,"enunciado":"Acerca da referência à organização da Administração Pública brasileira, julgue o item seguinte.\n\n\n\n\nEnquanto a governabilidade é implementada por meio de regras, normas e boas práticas de gestão, a governança deriva do apoio popular, do legislativo e da aceitação da autoridade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3759755,"enunciado":"Acerca da referência à organização da Administração Pública brasileira, julgue o item seguinte.\n\n\n\n\nA gestão por resultados qualifica‑se pelos resultados e impactos ao cidadão, e, também, rigor e adesão estrita às normas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3781486,"enunciado":"Com base nessa situação hipotética, julgue o item seguinte quanto aos atributos de qualidade no atendimento que se sobressaem nos servidores.\n\n\n\n\nA qualidade que se destaca em Abadia é a cortesia, enquanto Claudete zela pelo interesse no atendimento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3781487,"enunciado":"Com base nessa situação hipotética, julgue o item seguinte quanto aos atributos de qualidade no atendimento que se sobressaem nos servidores.\n\n\n\n\nElis foca na sua apresentação e Igor, na conduta.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3781488,"enunciado":"Com base nessa situação hipotética, julgue o item seguinte quanto aos atributos de qualidade no atendimento que se sobressaem nos servidores.\n\n\n\n\nGarcia demonstra tolerância, ao passo que Cleudete zela pela sua apresentação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3781489,"enunciado":"Com base nessa situação hipotética, julgue o item seguinte quanto aos atributos de qualidade no atendimento que se sobressaem nos servidores.\n\n\n\n\nCleudete é conhecida pela sua cortesia e Igor, pela conduta.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3781490,"enunciado":"Com base nessa situação hipotética, julgue o item seguinte quanto aos atributos de qualidade no atendimento que se sobressaem nos servidores.\n\n\n\n\nElis mostra interesse nos atendimentos e Abadia é notada por sua apresentação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3781492,"enunciado":"Quanto à postura profissional, ao atendimento telefônico e ao atendimento a clientes internos, julgue o item seguinte.\n\n\n\n\nPara causar boa impressão, o colaborador deve atender prontamente o telefone, no segundo ou terceiro toque, com saudação educada, informando o nome da organização e o seu próprio nome.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3781493,"enunciado":"Quanto à postura profissional, ao atendimento telefônico e ao atendimento a clientes internos, julgue o item seguinte.\n\n\n\n\nTratar colegas de forma indiferente ou não personalizar o atendimento dentro do possível é atitude avessa ao que se entende por atendimento a clientes internos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3932607,"enunciado":"Em relação a governança, julgue o item a seguir.\n\n\n\n\nA gestão efetiva de riscos requer conhecimento acerca do apetite ao risco e da cultura organizacional, sendo admitidas estratégias que abranjam desde a mitigação até a exploração deliberada do risco, visando obter maiores benefícios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3932608,"enunciado":"Em relação a governança, julgue o item a seguir.\n\n\n\n\nDe acordo com o Relatório Cadbury, a responsabilidade pela eficácia dos controles internos deve ser compartilhada solidariamente com os auditores externos, de modo a minimizar a responsabilidade do conselho de administração.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3932609,"enunciado":"Em relação a governança, julgue o item a seguir.\n\n\n\n\nO princípio da responsabilidade corporativa transcende a observância das obrigações legais, vinculando a atuação da organização à função social da propriedade e à sustentabilidade ambiental.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3932610,"enunciado":"Em relação a governança, julgue o item a seguir.\n\n\n\n\nA teoria dos stakeholders compatibiliza o dever ético da prestação de contas com a necessidade estratégica de priorizar grupos conforme seus atributos de poder, legitimidade e urgência, visando-se à sustentabilidade da organização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3932611,"enunciado":"Em relação a governança, julgue o item a seguir.\n\n\n\n\nA atuação da equipe de compliance tem caráter consultivo, devendo ser pautada pela neutralidade técnica na emissão de pareceres sobre a legislação vigente, a fim de evitar interferir na mudança de conduta de administradores e stakeholders.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3937106,"enunciado":"Em relação às noções de cidadania e relações públicas no âmbito de órgãos e entidades institucionais, julgue o item a seguir.\n\nAs atividades de relações públicas em um órgão de classe limitam‑se à divulgação institucional, não envolvendo ações voltadas à promoção da cidadania, ao diálogo com a sociedade ou ao fortalecimento da imagem institucional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3937117,"enunciado":"Considerando aspectos relacionados ao atendimento ao público e à postura profissional no ambiente institucional, julgue o item a seguir.\n\n\n\n\nA qualidade no atendimento ao público envolve a adoção de condutas como cortesia, atenção e objetividade, visando à satisfação do usuário dos serviços prestados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3937118,"enunciado":"Considerando aspectos relacionados ao atendimento ao público e à postura profissional no ambiente institucional, julgue o item a seguir.\n\n\n\n\nA eficiência no atendimento ao público está relacionada apenas à rapidez na prestação do serviço, independentemente da clareza das informações ou da postura do servidor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3937119,"enunciado":"Considerando aspectos relacionados ao atendimento ao público e à postura profissional no ambiente institucional, julgue o item a seguir.\n\n\n\n\nA tolerância e a discrição no atendimento ao público são elementos relevantes para a qualidade do serviço, especialmente em situações de conflito ou de tratamento de informações sensíveis.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3937120,"enunciado":"Considerando aspectos relacionados ao atendimento ao público e à postura profissional no ambiente institucional, julgue o item a seguir.\n\n\n\n\nA postura profissional adequada envolve conduta ética, respeito às normas institucionais e tratamento cordial no relacionamento com colegas e usuários dos serviços.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3937121,"enunciado":"Considerando aspectos relacionados ao atendimento ao público e à postura profissional no ambiente institucional, julgue o item a seguir.\n\n\n\n\nAs relações interpessoais no ambiente de trabalho são irrelevantes para o desempenho profissional, desde que o servidor execute corretamente as suas atribuições técnicas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3937122,"enunciado":"Considerando aspectos relacionados ao atendimento ao público e à postura profissional no ambiente institucional, julgue o item a seguir.\n\n\n\n\nNo atendimento telefônico, a objetividade justifica a supressão de saudações iniciais e a identificação do setor ou do atendente, desde que a informação solicitada seja prestada rapidamente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3937123,"enunciado":"Considerando aspectos relacionados ao atendimento ao público e à postura profissional no ambiente institucional, julgue o item a seguir.\n\n\n\n\nNo atendimento presencial, a resolução da demanda do usuário independe da postura do servidor, pois fatores como atenção, escuta ativa e linguagem adequada não interferem na qualidade do atendimento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3937124,"enunciado":"Considerando aspectos relacionados ao atendimento ao público e à postura profissional no ambiente institucional, julgue o item a seguir.\n\n\n\n\nNo atendimento a públicos internos e a públicos externos, a adoção de procedimentos padronizados elimina a necessidade de adaptação da comunicação e da conduta do servidor às especificidades de cada público.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3952075,"enunciado":"De acordo com a organização da Administração Pública, dos princípios e das diferenças entre gestão pública e privada, julgue o item a seguir.\n\n\n\n\nA gestão pública, ao contrário da privada, deve pautar‑se pela supremacia do interesse público sobre o privado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3952076,"enunciado":"De acordo com a organização da Administração Pública, dos princípios e das diferenças entre gestão pública e privada, julgue o item a seguir.\n\n\n\n\nA governança pública refere‑se aos mecanismos de liderança, de estratégia e de controle para avaliar, direcionar e monitorar a gestão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3952077,"enunciado":"De acordo com a organização da Administração Pública, dos princípios e das diferenças entre gestão pública e privada, julgue o item a seguir.\n\n\n\n\nA gestão por resultados na Administração Pública foca exclusivamente em processos, desconsiderando as entregas e os impactos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3952078,"enunciado":"De acordo com a organização da Administração Pública, dos princípios e das diferenças entre gestão pública e privada, julgue o item a seguir.\n\n\n\n\nO governo eletrônico utiliza tecnologias de informação para ampliar o acesso aos serviços públicos, promovendo transparência e participação cidadã.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":3952092,"enunciado":"Acerca da gestão de riscos, do compliance e dos controles internos, julgue o item a seguir.\n\n\n\n\nProgramas de compliance restringem‑se ao cumprimento de normas legais, excluindo padrões éticos e regulatórios internos da organização.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014730,"enunciado":"Em relação aos procedimentos administrativos e ao sistema de organização e métodos nas organizações públicas, julgue o item a seguir.\n\n\n\n\nOs procedimentos administrativos de gestão, que são centrados na movimentação interna, dispensam formalização documental, por não gerar efeitos externos ou por criar direitos para os particulares.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014732,"enunciado":"Em relação aos procedimentos administrativos e ao sistema de organização e métodos nas organizações públicas, julgue o item a seguir.\n\n\n\n\nA racionalização de formulários administrativos simplifica a coleta de dados e elimina informações repetitivas, contribuindo para a desburocratização e, inclusive, a eficiência da gestão documental.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014742,"enunciado":"Quanto ao desenvolvimento de equipes de trabalho e à cidadania nas organizações públicas, julgue o item a seguir.\n\n\n\n\nAo criar um canal transparente de denúncias anônimas, a organização estimula a participação ativa dos colaboradores, promovendo a cidadania organizacional e a ética no ambiente de trabalho.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014743,"enunciado":"Acerca da comunicação interna e externa e da redação oficial de documentos nas organizações públicas, julgue o item seguinte.\n\n\n\n\nPara agilizar as mudanças na fiscalização, o CRBM deve utilizar redes sociais informais como o principal canal oficial de comunicação com os servidores da área.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014751,"enunciado":"Em relação à qualidade no atendimento ao usuário dos serviços públicos, julgue o item seguinte.\n\n\n\n\nO servidor público deve priorizar a formalidade pujante, utilizando linguagem técnica e culta, para demonstrar conhecimento e autoridade ao cidadão durante o atendimento.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014752,"enunciado":"Em relação à qualidade no atendimento ao usuário dos serviços públicos, julgue o item seguinte.\n\n\n\n\nA presteza no atendimento público envolve o interesse em solucionar as solicitações com agilidade, sem, contudo, comprometer a qualidade e a veracidade das informações prestadas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014753,"enunciado":"Em relação à qualidade no atendimento ao usuário dos serviços públicos, julgue o item seguinte.\n\n\n\n\nQuando o servidor não conhece a resposta para a dúvida do usuário, deverá encerrar o atendimento imediatamente para não demonstrar despreparo ou ineficiência.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014754,"enunciado":"Em relação à qualidade no atendimento ao usuário dos serviços públicos, julgue o item seguinte.\n\n\n\n\nO servidor, ao perceber longa fila, pode simplificar formulário administrativo, dispensando documentos desnecessários previstos em norma obsoleta e focar no resultado final.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014755,"enunciado":"Em relação à qualidade no atendimento ao usuário dos serviços públicos, julgue o item seguinte.\n\n\n\n\nEm caso de usuário agressivo, o servidor deve justificar a negativa de atendimento educadamente, mas retirar a cortesia e a tolerância, que não são mútuas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014756,"enunciado":"Acerca da postura profissional durante o atendimento aos usuários dos serviços públicos, julgue o item a seguir. \n\n\n\n\nA postura profissional de excelência exige que o servidor sempre delegue o atendimento de conflitos interpessoais complexos à chefia imediata, visando preservar a autoridade da estrutura hierárquica.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014757,"enunciado":"Acerca da postura profissional durante o atendimento aos usuários dos serviços públicos, julgue o item a seguir. \n\n\n\n\nA postura proativa no atendimento autoriza o servidor a flexibilizar prazos regimentais em situações de vulnerabilidade social, visando à humanização imediata das relações interpessoais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014758,"enunciado":"Acerca da postura profissional durante o atendimento aos usuários dos serviços públicos, julgue o item a seguir. \n\n\n\n\nNo atendimento presencial de alta demanda, observados os critérios legais, o servidor poderá utilizar a triagem técnica para classificar a complexidade dos pleitos, otimizando o tempo de espera coletivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014759,"enunciado":"Acerca da postura profissional durante o atendimento aos usuários dos serviços públicos, julgue o item a seguir. \n\n\n\n\nNo atendimento interno, a comunicação lateral entre departamentos tem o condão de reduzir a sobrecarga da hierarquia, agilizando a tomada de decisão e a resolução de problemas intersetoriais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4014765,"enunciado":"Acerca do trabalho em equipe nas organizações públicas, julgue o item seguinte.\n\n\n\n\nCom o intuito de otimizar o atendimento ao cidadão, o servidor deverá utilizar a escuta ativa, que consiste em uma técnica focada na concordância imediata com as demandas para validar o interlocutor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019438,"enunciado":"No que diz respeito às funções administrativas clássicas e à sua aplicação no contexto das organizações públicas, julgue o item a seguir.\n\n\n\n\nEmbora tradicionalmente apresentadas de forma sequencial, as funções administrativas – planejamento, organização, direção e controle – são interdependentes e podem ocorrer simultaneamente no cotidiano das organizações públicas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019441,"enunciado":"No que diz respeito às funções administrativas clássicas e à sua aplicação no contexto das organizações públicas, julgue o item a seguir.\n\n\n\n\nEm situação de escassez de recursos, priorizar a função de direção em detrimento das outras funções administrativas garante o sucesso organizacional, pois a liderança motiva os servidores independentemente do planejamento e do controle.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019443,"enunciado":"Acerca das noções de administração financeira, de pessoas e de materiais nas organizações públicas, julgue o item seguinte.\n\n\n\n\nNa Administração Pública, o princípio da economicidade orienta que se busque a melhor relação custo‑benefício nas aquisições e nas contratações, compatibilizando qualidade com menor dispêndio de recursos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019464,"enunciado":"Acerca dos conceitos de cidadania, de relações públicas e de responsabilidade social no serviço público, julgue o item a seguir.\n\n\n\n\nAs relações públicas na Administração Pública restringem‑se à divulgação de ações institucionais, não abrangendo o diálogo com a sociedade nem a construção de canais de participação cidadã.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019465,"enunciado":"Acerca da comunicação organizacional, da redação oficial e dos tipos de documentos administrativos, julgue o item seguinte.\n\n\n\n\nA comunicação interna eficiente contribui para o alinhamento das ações administrativas e para a redução de ruídos institucionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019474,"enunciado":"Quanto à qualidade no atendimento ao público e à postura profissional do servidor, julgue o item seguinte.\n\n\n\n\nO atendimento ao público, seja presencial ou por meio de canais remotos, constitui importante interface institucional e influencia diretamente a percepção do cidadão a respeito da qualidade e da eficiência dos serviços públicos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019475,"enunciado":"Quanto à qualidade no atendimento ao público e à postura profissional do servidor, julgue o item seguinte.\n\n\n\n\nA postura profissional do servidor, ao integrar elementos como cordialidade, discrição, ética e comprometimento, reflete não apenas condutas individuais, mas também valores e princípios institucionais percebidos pelo usuário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019476,"enunciado":"Quanto à qualidade no atendimento ao público e à postura profissional do servidor, julgue o item seguinte.\n\n\n\n\nA objetividade no atendimento é incompatível com a cordialidade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019477,"enunciado":"Quanto à qualidade no atendimento ao público e à postura profissional do servidor, julgue o item seguinte.\n\n\n\n\nUm servidor que recebe um cidadão visivelmente nervoso deve manter distanciamento emocional completo, evitando demonstrar empatia para preservar a impessoalidade exigida no serviço público.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019478,"enunciado":"Quanto à qualidade no atendimento ao público e à postura profissional do servidor, julgue o item seguinte.\n\n\n\n\nA qualidade no atendimento ao público mensura‑se exclusivamente pela rapidez no fornecimento de respostas, sendo a precisão e a confiabilidade das informações aspectos secundários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019479,"enunciado":"Quanto ao atendimento telefônico, ao atendimento presencial e aos públicos interno e externo, julgue o item a seguir.\n\n\n\n\nNo atendimento telefônico, além da clareza e da objetividade na transmissão de informações, a identificação do servidor e do setor contribui para a transparência e o profissionalismo da interação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4019480,"enunciado":"Quanto ao atendimento telefônico, ao atendimento presencial e aos públicos interno e externo, julgue o item a seguir.\n\n\n\n\nO atendimento interno entre setores, por tratar de relações internas à organização e não envolver o público externo, dispensa formalidades e padrões de qualidade mais rigorosos, sendo suficiente a comunicação informal e espontânea, para que se assegure o bom funcionamento dos fluxos administrativos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4120746,"enunciado":"Julgue o item seguinte, acerca das funções administrativas nas organizações públicas.\n\n\n\n\nAo realizar a alocação de pessoal e de recursos materiais entre os departamentos de uma organização pública para melhorar a eficiência, o gestor pratica a função administrativa de organização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4241138,"enunciado":"A capacidade de o servidor público prestar atendimento ao público com confiança e exatidão é exemplo de confiabilidade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]},{"id":4241139,"enunciado":"A aparência das instalações físicas não interfere na qualidade do atendimento ao público prestado por uma organização estatal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["administracao_publica_agp"]}];
